            // Helpers for Date Formatting
            const getOrdinal = (n) => {
                const s = ["th", "st", "nd", "rd"];
                const v = n % 100;
                return n + (s[(v - 20) % 10] || s[v] || s[0]);
            };

            const formatDateParts = (dateStr) => {
                if (!dateStr) return { day: '______', monthYear: '____________________' };
                const d = new Date(dateStr);
                const day = getOrdinal(d.getDate());
                const monthYear = d.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
                return { day, monthYear };
            };

            const formatAadhar = (str) => {
                if (!str) return '________________';
                const clean = str.replace(/\s/g, '');
                if (clean.length === 12) {
                    return `XXXX XXXX ${clean.slice(-4)}`;
                }
                return str;
            };

            const formatPan = (str) => {
                if (!str) return '__________';
                // Request: Hide second digit mask (AxUxSx3x2x style)
                // Replaces every character at an odd index (2nd, 4th, etc.) with 'X'
                return str.toUpperCase().split('').map((c, i) => i % 2 === 1 ? 'X' : c).join('');
            };

