                                                        TM48: 'bg-orange-100 text-orange-800',
                                                        GNIDA_PACKAGE: 'bg-amber-100 text-amber-800',
                                                        KYA: 'bg-yellow-100 text-yellow-800',
                                                        TM_APP: 'bg-rose-100 text-rose-800',
